    ListView(padding:const EdgeInsets.all(16),children:[OutlinedButton.icon(onPressed:busy?null:()=>action(() async {await widget.client.refresh(widget.store);message='Surveys and permissions refreshed.';}),icon:const Icon(Icons.cloud_download),label:const Text('Download published surveys')),if(versions.isEmpty)const Padding(padding:EdgeInsets.all(30),child:Text('No surveys cached. Publish a version in the web app first.')),for(final v in versions)Card(child:Column(children:[ListTile(title:Text(v['schema']['form_name']),subtitle:Text('${projects.firstWhere((p)=>p['id']==v['project_id'])['name']} · version ${v['number']}'),trailing:const Icon(Icons.chevron_right),onTap:busy?null:()=>action(()=>open(v))),TextButton(onPressed:busy?null:()=>export(versionId:v['id']),child:const Text('Export this survey version'))]))]),
